    def generate_xml(self):
        doc = Document()
        rootElement = doc.createElement('CommandList')
        rootElement.setAttribute('Repeat', '1')
        syncElement = doc.createElement('Synchronize')
        syncElement.setAttribute('type', '0')
        commandElement = doc.createElement('Command')
        commandElement.setAttribute('Repeat', '10')
        name = doc.createElement('name')
        name.appendChild(doc.createTextNode('ping'))
        id = doc.createElement('ID')
        id.appendChild(doc.createTextNode('0x0604'))
        netLink = doc.createElement('NetLink')
        netLink.appendChild(doc.createTextNode('1'))
        ip = doc.createElement('IP')
        ip.appendChild(doc.createTextNode('10.97.65.244'))
        packagesize = doc.createElement('Packagesize')
        packagesize.appendChild(doc.createTextNode('200'))
        interval = doc.createElement('Interval')
        interval.appendChild(doc.createTextNode('1'))
        timeout = doc.createElement('TimeOut')
        timeout.appendChild(doc.createTextNode('15'))
        sortIndex = doc.createElement('SortIndex')
        sortIndex.appendChild(doc.createTextNode('1'))
        commandElement.appendChild(name)
        commandElement.appendChild(id)
        commandElement.appendChild(netLink)
        commandElement.appendChild(ip)
        commandElement.appendChild(packagesize)
        commandElement.appendChild(interval)
        commandElement.appendChild(timeout)
        commandElement.appendChild(sortIndex)
        print(commandElement)
        syncElement.appendChild(commandElement)
        print(syncElement)
        rootElement.appendChild(syncElement)
        print(rootElement)
        doc.appendChild(rootElement)
        ping1_xml = os.path.join(os.getcwd(), 'ping1_xml')
        print(ping1_xml)
        f = open(ping1_xml, 'w')
        doc.writexml(f, addindent='  ', newl='\n', encoding='utf-8')
        f.close()
        return doc

