    def get_mac_tp(self, cmd="GetParamMAC"):
        """
        Get throughput on UE
        :param cmd: GetParamMAC define by sigspark api
        :return <tuple> (ul , dl)  (byte)
        """
        self._send_msg(cmd)
        res = self._get_msg(cmd)
        ul = float(res['MACUL'])
        dl = float(res['MACDL'])
        return (ul, dl)

    def get_tput(self, cmd="GetParamValue"):
        """
        Get throughput on UE
        :param cmd: GetParamMAC define by sigspark api
        :return <tuple> (ul , dl)  (byte)
        """

        param = ["NR MAC Thr. UL [Mbps]",
                 "NR MAC Thr. DL [Mbps]"
                 ]
        self._send_msg(cmd, param=param)
        res = self._get_msg(cmd)
        print(res)
        tput = res['Values']
        print(tput)
        ul = float(tput[0])
